<?php use App\Core\Authorization;use App\Core\Csrf; ?>
<div class="page-heading"><div><p class="eyebrow"><?=e($event['status'])?> event</p><h1><?=e($event['title'])?></h1><p><?=e(date('M j, Y g:i A',strtotime($event['starts_at'])))?> – <?=e(date('M j, Y g:i A',strtotime($event['ends_at'])))?></p></div><?php if(Authorization::allows('events.edit')):?><a class="button primary" href="<?=e(url('/events/'.$event['id'].'/edit'))?>">Edit event</a><?php endif;?></div>
<div class="detail-grid"><section class="card form-section"><h2>Details</h2><dl><dt>Venue</dt><dd><?=e($event['venue']?:'—')?></dd><dt>Organizer</dt><dd><?=e($event['organizer'])?></dd><dt>Visibility</dt><dd><?=e($event['visibility'])?></dd><dt>Capacity</dt><dd><?=e($event['capacity']?:'Unlimited')?></dd></dl><p><?=nl2br(e($event['description']))?></p></section><?php if($canManage):?><section class="card form-section"><h2>Add participant</h2><form method="post" action="<?=e(url('/events/'.$event['id'].'/participants'))?>" class="stack-form"><?=Csrf::field()?><label>Participant type<select name="participant_type" data-participant-type><option value="student">Student</option><option value="teacher">Teacher</option></select></label><label>Student or teacher<select name="profile_id" data-profile-select><optgroup label="Students" data-group="student"><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=e($s['last_name'].', '.$s['first_name'].' — '.$s['student_no'])?></option><?php endforeach;?></optgroup><optgroup label="Teachers" data-group="teacher" hidden><?php foreach($teachers as $t):?><option value="<?=$t['id']?>"><?=e($t['last_name'].', '.$t['first_name'].' — '.$t['employee_no'])?></option><?php endforeach;?></optgroup></select></label><button class="button primary">Add participant</button></form></section><?php endif;?></div>
<form method="post" action="<?=e(url('/events/'.$event['id'].'/attendance'))?>"><?=Csrf::field()?><section class="card table-card section-card"><div class="table-heading"><div><h2>Participants and attendance</h2><small><?=count($participants)?> registered records</small></div><?php if($canManage):?><button type="button" class="button small" data-check-in>Mark all present</button><?php endif;?></div><table class="attendance-table"><thead><tr><th>Participant</th><th>Type</th><th>Status</th><th>Check in</th><th>Check out</th><th>Remarks</th></tr></thead><tbody><?php foreach($participants as $p):?><tr><td><strong><?=e($p['participant_name'])?></strong><br><small><?=e($p['reference_no'])?></small></td><td><?=e($p['participant_type'])?></td><td><select class="status-select" name="attendance[<?=$p['id']?>][status]" <?=$canManage?'':'disabled'?>><?php foreach($attendanceStatuses as $x):?><option value="<?=$x?>" <?=($p['attendance_status']??'unrecorded')===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select></td><td><input type="datetime-local" name="attendance[<?=$p['id']?>][checked_in_at]" value="<?=e($p['checked_in_at']?date('Y-m-d\TH:i',strtotime($p['checked_in_at'])):'')?>" <?=$canManage?'':'disabled'?>></td><td><input type="datetime-local" name="attendance[<?=$p['id']?>][checked_out_at]" value="<?=e($p['checked_out_at']?date('Y-m-d\TH:i',strtotime($p['checked_out_at'])):'')?>" <?=$canManage?'':'disabled'?>></td><td><input name="attendance[<?=$p['id']?>][remarks]" value="<?=e($p['attendance_remarks'])?>" <?=$canManage?'':'disabled'?>></td></tr><?php endforeach;?><?php if(!$participants):?><tr><td colspan="6" class="empty">No participants registered yet.</td></tr><?php endif;?></tbody></table></section><?php if($canManage&&$participants):?><div class="sticky-actions"><button class="button primary">Save event attendance</button></div><?php endif;?></form>
<script>const type=document.querySelector('[data-participant-type]'),select=document.querySelector('[data-profile-select]');type?.addEventListener('change',()=>{select.querySelectorAll('optgroup').forEach(g=>{g.hidden=g.dataset.group!==type.value;g.querySelectorAll('option').forEach(o=>o.disabled=g.hidden)});select.value=select.querySelector('optgroup:not([hidden]) option')?.value||''});document.querySelector('[data-check-in]')?.addEventListener('click',()=>document.querySelectorAll('.status-select').forEach(x=>x.value='present'));</script>
